import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { name4Schema, type Name4 } from "./unions/name4.js";

export type StreamedFunctionResult = {
  /**
   * The arguments for calling the function, generated by the model in JSON format. Ensure to
   * validate these arguments in your code before invoking the function since the model may not
   * always produce valid JSON.
   */
  arguments: string;
  /** The name of the function to call. */
  name?: Name4;
};

export const streamedFunctionResultSchema: Schema<StreamedFunctionResult> = s.object<StreamedFunctionResult>({
  arguments: s.string(),
  name: s.optional(s.lazy(() => name4Schema)),
});
